package com.observability.commerce;
import org.slf4j.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;
@Component public class BackgroundJobs { private final JdbcTemplate db; private static final Logger log=LoggerFactory.getLogger(BackgroundJobs.class); public BackgroundJobs(JdbcTemplate d){db=d;} @Scheduled(fixedDelayString="${INVENTORY_JOB_INTERVAL_MS:60000}") public void inventoryMonitor(){Integer n=db.queryForObject("SELECT count(*) FROM inventory WHERE quantity<=reorder_level",Integer.class);log.info("Inventory monitor detected {} low-stock products",n);} @Scheduled(fixedDelayString="${ORDER_PROCESSOR_INTERVAL_MS:30000}") public void processOrders(){log.info("Order processor heartbeat");} }
